package com.example.billing.service;
import static com.example.billing.api.Contracts.*;import static com.example.billing.domain.BillingConstants.*;import com.example.billing.persistence.Repositories.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class SubscriptionService {private final SubscriptionRepository subscriptions;private final CustomerRepository customers;private final PricePlanRepository plans;private final Clock clock;public SubscriptionService(SubscriptionRepository s,CustomerRepository c,PricePlanRepository p,Clock clock){subscriptions=s;customers=c;plans=p;this.clock=clock;}public SubscriptionResponse create(CreateSubscriptionRequest r){if(customers.findById(r.customerId()).filter(x->CustomerStatus.ACTIVE.equals(x.status)).isEmpty())throw new IllegalStateException("Customer does not exist or is not active.");var plan=plans.findByIdAndActiveTrue(r.pricePlanId()).orElseThrow(()->new IllegalArgumentException("Price plan does not exist."));var start=r.startDate()==null?LocalDate.now(clock):r.startDate();var x=new com.example.billing.domain.Subscription();x.id=UUID.randomUUID();x.customerId=r.customerId();x.pricePlanId=r.pricePlanId();x.status=SubscriptionStatus.ACTIVE;x.startDate=start;x.currentPeriodStart=start;x.currentPeriodEnd=periodEnd(start,plan.billingInterval);return SubscriptionResponse.from(subscriptions.save(x));}@Transactional(readOnly=true)public SubscriptionResponse get(UUID id){return subscriptions.findById(id).map(SubscriptionResponse::from).orElse(null);}@Transactional(readOnly=true)public List<SubscriptionResponse> list(UUID id){return subscriptions.findByCustomerIdOrderByStartDateAscIdAsc(id).stream().map(SubscriptionResponse::from).toList();}public SubscriptionResponse cancel(UUID id,CancelSubscriptionRequest r){var x=subscriptions.findById(id).orElse(null);if(x==null)return null;if(r.cancelAtPeriodEnd())x.cancelAtPeriodEnd=true;else{x.status=SubscriptionStatus.CANCELED;x.cancelAtPeriodEnd=false;}return SubscriptionResponse.from(x);}public ChangeSubscriptionPlanResponse changePlan(UUID id,ChangeSubscriptionPlanRequest r){var x=subscriptions.findById(id).orElse(null);if(x==null)return null;if(!SubscriptionStatus.ACTIVE.equals(x.status))throw new IllegalStateException("Only active subscriptions can change plans.");var current=plans.findById(x.pricePlanId).orElseThrow(()->new IllegalStateException("Subscription does not have a current price plan."));var next=plans.findByIdAndActiveTrue(r.pricePlanId()).orElseThrow(()->new IllegalArgumentException("Price plan does not exist."));var p=prorate(current.amount,next.amount,x.currentPeriodStart,x.currentPeriodEnd,LocalDate.now(clock));x.pricePlanId=next.id;x.cancelAtPeriodEnd=false;return new ChangeSubscriptionPlanResponse(SubscriptionResponse.from(x),p);}public static ProrationResult prorate(BigDecimal current,BigDecimal next,LocalDate start,LocalDate end,LocalDate change){if(!end.isAfter(start))throw new IllegalArgumentException("Period end must be after period start.");long total=Duration.between(start.atStartOfDay(),end.atStartOfDay()).toDays();long remaining=!change.isAfter(start)?total:!change.isBefore(end)?0:Duration.between(change.atStartOfDay(),end.atStartOfDay()).toDays();var credit=portion(current,remaining,total);var cost=portion(next,remaining,total);return new ProrationResult(credit,cost,cost.subtract(credit));}private static BigDecimal portion(BigDecimal a,long r,long t){return a.multiply(BigDecimal.valueOf(r)).divide(BigDecimal.valueOf(t),2,RoundingMode.HALF_UP);}private static LocalDate periodEnd(LocalDate s,String i){return switch(i){case BillingInterval.MONTH->s.plusMonths(1);case BillingInterval.YEAR->s.plusYears(1);default->throw new UnsupportedOperationException("Billing interval '"+i+"' is not supported.");};}}
